import {
  ORDER_STAGES, LEAD_STATUSES, MANAGERS, SOURCES,
  seedLeads, seedQuotes, seedOrders, calculateQuote, quoteCost, nextId,
  orderStageIndex, nextOrderStage, clientStage, filterLeads, filterOrders,
  sourceStats, managerStats, financeStats, dashboardStats, funnelStats, lostReasons
} from './auto-sale-core.mjs';
import {
  QUOTE_STATUSES,RISK_TYPES,PAYMENT_METHODS,leadTransitionAllowed,
  validateClientRequest,validateManagerLead,validateLeadUpdate,validateQuote,
  canCreateOrder,validateOrderUpdate,normalizePayments,paymentsTotal,nextPaymentId
} from './auto-sale-business-rules.mjs';

const root=document.querySelector('#app');
if(!root)throw new Error('AUTO SALE root not found');
const today=new Date().toISOString().slice(0,10);
const addDays=(date,days)=>{const d=new Date(`${date}T00:00:00Z`);d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)};
const SOURCE_OPTIONS=[...new Set([...SOURCES,'Mini App','Телефон','Офис'])];
const cars=[
{id:'bmw-x5-22',brand:'BMW',model:'X5 xDrive40i',year:2022,mileage:'38 000 км',engine:'3.0 бензин',drive:'AWD',auction:'Copart',price:46800,delivery:'8–11 недель',tag:'Premium SUV',image:'https://images.unsplash.com/photo-1555215695-3004980ad54e?auto=format&fit=crop&w=1400&q=82'},
{id:'tesla-y-23',brand:'Tesla',model:'Model Y Long Range',year:2023,mileage:'21 000 км',engine:'Electric',drive:'AWD',auction:'IAAI',price:39700,delivery:'7–10 недель',tag:'EV',image:'https://images.unsplash.com/photo-1617788138017-80ad40651399?auto=format&fit=crop&w=1400&q=82'},
{id:'rav4-22',brand:'Toyota',model:'RAV4 XLE Premium',year:2022,mileage:'42 000 км',engine:'2.5 бензин',drive:'AWD',auction:'Copart',price:31800,delivery:'8–12 недель',tag:'Family SUV',image:'https://images.unsplash.com/photo-1623869675781-80aa31012a5a?auto=format&fit=crop&w=1400&q=82'},
{id:'mustang-mach-e',brand:'Ford',model:'Mustang Mach-E',year:2022,mileage:'29 000 км',engine:'Electric',drive:'AWD',auction:'IAAI',price:34400,delivery:'7–10 недель',tag:'EV',image:'https://images.unsplash.com/photo-1614200187524-dc4b892acf16?auto=format&fit=crop&w=1400&q=82'},
{id:'gle-21',brand:'Mercedes-Benz',model:'GLE 350 4MATIC',year:2021,mileage:'51 000 км',engine:'2.0 бензин',drive:'AWD',auction:'Manheim',price:52100,delivery:'8–12 недель',tag:'Premium SUV',image:'https://images.unsplash.com/photo-1618843479313-40f8afb4b4d8?auto=format&fit=crop&w=1400&q=82'},
{id:'lexus-rx-22',brand:'Lexus',model:'RX 350 F Sport',year:2022,mileage:'33 000 км',engine:'3.5 бензин',drive:'AWD',auction:'Copart',price:43800,delivery:'8–11 недель',tag:'Premium SUV',image:'https://images.unsplash.com/photo-1606664515524-ed2f786a0bd6?auto=format&fit=crop&w=1400&q=82'}
];
const KEYS={leads:'auto-sale-leads-v2',quotes:'auto-sale-quotes-v2',orders:'auto-sale-orders-v2',notes:'auto-sale-notes-v2',legacy:'auto-sale-orders-v1',role:'auto-sale-role-v2'};
const parse=(storage,key,fallback)=>{try{const x=JSON.parse(storage.getItem(key)||'null');return x??fallback}catch{return fallback}};
const persist=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>'$'+new Intl.NumberFormat('en-US',{maximumFractionDigits:0}).format(Number(v)||0);
const dateRu=v=>{if(!v)return'—';const d=new Date(`${v}T00:00:00`);return Number.isNaN(d.getTime())?esc(v):d.toLocaleDateString('ru-RU',{day:'2-digit',month:'short'})};
const dateTimeRu=v=>{const d=new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})};
const showErrors=(form,errors)=>{let box=form.querySelector('.auto-form-error');if(!box){box=document.createElement('div');box.className='auto-form-error full';form.prepend(box)}box.innerHTML=errors.map(x=>`<span>${esc(x)}</span>`).join('')};

let leads=parse(localStorage,KEYS.leads,null)||seedLeads();
let quotes=parse(localStorage,KEYS.quotes,null)||seedQuotes();
let orders=parse(localStorage,KEYS.orders,null)||seedOrders();
let notes=parse(localStorage,KEYS.notes,{});
const legacy=parse(localStorage,KEYS.legacy,[]);
if(Array.isArray(legacy))for(const req of legacy){const sig=`${req.name||''}|${req.contact||''}|${req.model||''}`;if(!leads.some(x=>`${x.name||''}|${x.contact||''}|${x.model||''}`===sig))leads.push({id:nextId('L',leads),name:req.name||'Клиент',contact:req.contact||'',model:req.model||'Автомобиль под заказ',budget:Number(req.budget)||0,source:'Mini App',manager:'Дмитрий',status:'Новый',priority:'Средний',createdAt:req.createdAt||new Date().toISOString(),nextAction:today,note:req.note||'',clientCreated:true});}
leads=leads.map(x=>({...x,yearFrom:x.yearFrom||'',yearTo:x.yearTo||'',mileageMax:x.mileageMax||'',engine:x.engine||'Не важно',drive:x.drive||'Не важно',damage:x.damage||'Минимальные',deliveryCity:x.deliveryCity||'',deposit:Number(x.deposit)||0,depositDate:x.depositDate||'',paymentMethod:x.paymentMethod||''}));
quotes=quotes.map(x=>({...x,version:Number(x.version)||1,validUntil:x.validUntil||addDays(today,7)}));
orders=orders.map(x=>{const payments=normalizePayments(x);const riskType=x.riskType||(x.risk==='Нет'?'Нет':RISK_TYPES.includes(x.risk)?x.risk:'Другое');const riskNote=x.riskNote||(riskType==='Другое'?x.risk:'');return{...x,payments,paid:paymentsTotal(payments),riskType,riskNote}});
const saveAll=()=>{persist(KEYS.leads,leads);persist(KEYS.quotes,quotes);persist(KEYS.orders,orders);persist(KEYS.notes,notes)};saveAll();

const roleLabels={client:'Клиент',manager:'Менеджер',owner:'Директор'};
const nav={client:[['home','Главная','⌂'],['catalog','Авто','▦'],['orders','Мои заказы','◫'],['about','Как работаем','◎']],manager:[['work','Работа','⌘'],['leads','Лиды','◫'],['quotes','Расчёты','▤'],['shipping','Логистика','↔']],owner:[['overview','Обзор','◉'],['pipeline','Продажи','▥'],['finance','Финансы','$'],['ordersAdmin','Заказы','◆']]};
const savedRole=sessionStorage.getItem(KEYS.role);
const state={role:nav[savedRole]?savedRole:'client',route:'home',query:'',brand:'all',budget:'all',leadQuery:'',leadStatus:'all',leadSource:'all',leadManager:'all',orderQuery:'',orderStage:'all',orderManager:'all',orderRisk:'all',modal:null};
state.route=nav[state.role][0][0];
const dashboard=()=>dashboardStats(leads,orders,quotes);
const finances=()=>financeStats(orders);
const taskDue=l=>l.nextAction&&l.nextAction<=today&&!['Сделка','Отказ'].includes(l.status);
const orderRisk=o=>(o.riskType||o.risk||'Нет')==='Нет'?'Нет':(o.riskNote||o.riskType||o.risk);
const statusClass=v=>/Отказ|риск|Документ|ожида|Новый|Черновик|уточ|Задерж/i.test(v||'')?'warn':/Сделка|Согласован|В море|Тамож|Выдача|Нет/i.test(v||'')?'good':'';
function brand(){return `<button class="auto-brand" data-go="${nav[state.role][0][0]}"><span class="auto-brand-mark">AS</span><span><b>AUTO SALE</b><small>USA IMPORT</small></span></button>`}
function shell(content){const d=dashboard(),f=finances();return `<div class="auto-shell"><header class="auto-topbar">${brand()}<div class="auto-role-switch">${Object.entries(roleLabels).map(([id,label])=>`<button data-role="${id}" class="${state.role===id?'active':''}">${label}</button>`).join('')}</div></header>${state.role!=='client'?`<div class="auto-role-strip"><span>${state.role==='manager'?'Рабочая панель менеджера':'Панель директора'}</span><b>${state.role==='manager'?`${d.activeLeads} активных лидов · ${d.risky} риска`:`${money(f.turnover)} оборот · ${d.conversion}% конверсия`}</b><small>Демо-данные · бизнес-правила включены</small></div>`:''}<main class="auto-main">${content}</main><nav class="auto-bottom">${nav[state.role].map(([id,label,ico])=>`<button data-go="${id}" class="${state.route===id?'active':''}"><strong>${ico}</strong><span>${label}</span></button>`).join('')}</nav>${state.modal?modal():''}</div>`}

function hero(){return `<section class="auto-hero"><div><span class="auto-eyebrow">AUTO SALE · США → ПОД ЗАКАЗ</span><h1>Автомобиль из США под ключ.</h1><p>Подбор, проверка, согласованный расчёт, выкуп, доставка и прозрачный статус заказа в одном приложении.</p><div class="auto-actions"><button class="auto-btn primary" data-open-request>Получить расчёт</button><button class="auto-btn ghost" data-go="catalog">Смотреть варианты</button></div></div><div class="auto-hero-stats"><div class="auto-stat"><span>Расчёт до покупки</span><b>под ключ</b></div><div class="auto-stat"><span>Проверка истории</span><b>VIN + фото</b></div><div class="auto-stat"><span>Срок поставки</span><b>7–12 нед.</b></div><div class="auto-stat"><span>Статус заказа</span><b>онлайн</b></div></div></section>`}
function process(){const steps=[['01','Запрос','Фиксируем требования и бюджет.'],['02','Подбор','Находим и проверяем подходящие лоты.'],['03','Расчёт','Согласуем полную стоимость и депозит.'],['04','Выкуп и доставка','Аукцион → порт → море → таможня.'],['05','Выдача','Документы, финальный расчёт и передача авто.']];return `<section class="auto-section"><div class="auto-section-head"><div><span class="auto-eyebrow">ПРОЦЕСС</span><h2>Каждый этап фиксируется в системе</h2></div><p>Следующий шаг доступен только когда заполнены данные предыдущего.</p></div><div class="auto-process">${steps.map(s=>`<article class="auto-step"><i>${s[0]}</i><b>${s[1]}</b><span>${s[2]}</span></article>`).join('')}</div></section>`}
function carCard(c){return `<article class="auto-car"><div class="auto-car-media"><img src="${c.image}" alt="${esc(c.brand+' '+c.model)}"><span class="auto-chip">${c.tag}</span></div><div class="auto-car-body"><div class="auto-car-top"><div><small>${c.year} · ${c.auction}</small><h3>${esc(c.brand+' '+c.model)}</h3></div><div class="auto-price"><b>от ${money(c.price)}</b><span>ориентир под ключ</span></div></div><div class="auto-specs"><span>${c.mileage}</span><span>${c.engine}</span><span>${c.drive}</span></div><div class="auto-card-actions"><button class="auto-btn primary" data-request-car="${c.id}">Рассчитать</button><button class="auto-btn ghost" data-detail="${c.id}">Подробнее</button></div></div></article>`}
function home(){return hero()+process()+`<section class="auto-section"><div class="auto-section-head"><div><span class="auto-eyebrow">ПРИМЕРЫ</span><h2>Что можно привезти сейчас</h2></div><button class="auto-btn ghost" data-go="catalog">Весь каталог →</button></div><div class="auto-grid">${cars.slice(0,3).map(carCard).join('')}</div></section>`}
function filteredCars(){return cars.filter(c=>{const q=state.query.toLowerCase().trim();return(!q||`${c.brand} ${c.model} ${c.year} ${c.engine}`.toLowerCase().includes(q))&&(state.brand==='all'||c.brand===state.brand)&&(state.budget==='all'||state.budget==='35'&&c.price<=35000||state.budget==='45'&&c.price>35000&&c.price<=45000||state.budget==='46'&&c.price>45000)})}
function catalog(){const rows=filteredCars(),brands=[...new Set(cars.map(c=>c.brand))];return `<section class="auto-section"><div class="auto-section-head"><div><span class="auto-eyebrow">АВТО ИЗ США</span><h2>Варианты для заказа</h2></div><p>Финальная цена формируется только по конкретному лоту.</p></div><div class="auto-filters"><input id="autoSearch" placeholder="Поиск: BMW, Tesla, RAV4…" value="${esc(state.query)}"><select id="brandFilter"><option value="all">Все марки</option>${brands.map(b=>`<option value="${esc(b)}" ${state.brand===b?'selected':''}>${esc(b)}</option>`).join('')}</select><select id="budgetFilter"><option value="all">Любой бюджет</option><option value="35" ${state.budget==='35'?'selected':''}>до $35 000</option><option value="45" ${state.budget==='45'?'selected':''}>$35–45 000</option><option value="46" ${state.budget==='46'?'selected':''}>от $45 000</option></select></div><div class="auto-grid">${rows.length?rows.map(carCard).join(''):`<div class="auto-empty">По заданным фильтрам вариантов нет.</div>`}</div></section>`}
function timeline(stage){const idx=orderStageIndex(stage);return `<div class="auto-timeline auto-timeline-full">${ORDER_STAGES.map((s,i)=>`<span class="${i<=idx?'done':''}">${s}</span>`).join('')}</div>`}
function clientOrders(){const clientLeads=leads.filter(x=>x.clientCreated);const cards=clientLeads.map(lead=>{const order=orders.find(x=>x.leadId===lead.id),quote=quotes.filter(x=>x.leadId===lead.id).sort((a,b)=>b.version-a.version)[0],stage=clientStage(lead,order);return `<article class="auto-order-card"><div class="auto-order-head"><div><h3>${esc(order?.model||lead.model)}</h3><small>${esc(lead.id)} · менеджер ${esc(lead.manager||'назначается')}</small></div><div class="auto-price"><b>${quote?.total?money(quote.total):lead.budget?`до ${money(lead.budget)}`:'по расчёту'}</b><span>${order?.stage||quote?.status||lead.status}</span></div></div>${timeline(stage)}<div class="auto-order-meta"><span><b>Следующий шаг</b>${order?`ETA ${dateRu(order.eta)}`:`${dateRu(lead.nextAction)} · ${esc(lead.status)}`}</span><span><b>Параметры</b>${esc(lead.yearFrom||'—')}–${esc(lead.yearTo||'—')} · до ${esc(lead.mileageMax||'—')} км</span></div></article>`}).join('');return `<section class="auto-section"><div class="auto-section-head"><div><span class="auto-eyebrow">МОИ ЗАКАЗЫ</span><h2>Заявки и статус поставки</h2></div><button class="auto-btn primary" data-open-request>Новый запрос</button></div>${cards||'<div class="auto-empty">Ваших заявок пока нет.</div>'}</section>`}
function about(){return process()+`<section class="auto-panel-grid"><article class="auto-panel"><h3>До выкупа</h3><p class="auto-muted-copy">Клиент получает проверенный вариант и согласованный расчёт. Заказ появляется только после согласования цены и фиксации депозита.</p></article><article class="auto-panel"><h3>После выкупа</h3><p class="auto-muted-copy">LOT, VIN, ETA, локация, риски и история платежей ведутся в карточке заказа и доступны для контроля.</p></article></section>`}

function kpi(label,value,sub='',tone=''){return `<div class="auto-kpi ${tone}"><span>${label}</span><b>${value}</b>${sub?`<small>${sub}</small>`:''}</div>`}
function leadStatusBadge(l){return `<span class="auto-status ${statusClass(l.status)}">${esc(l.status)}</span>`}
function leadTable(rows){return `<div class="auto-data-table"><div class="auto-data-head"><span>Клиент / запрос</span><span>Бюджет</span><span>Источник</span><span>Менеджер</span><span>Статус</span><span></span></div>${rows.map(l=>`<button class="auto-data-row" data-lead="${l.id}"><span><b>${esc(l.name)}</b><small>${esc(l.model)}</small></span><span>${l.budget?money(l.budget):'уточнить'}</span><span>${esc(l.source)}</span><span>${esc(l.manager)}</span>${leadStatusBadge(l)}<span class="auto-row-action">→</span></button>`).join('')}</div>`}
function managerWork(){const d=dashboard(),due=leads.filter(taskDue).slice(0,5),risky=orders.filter(o=>orderRisk(o)!=='Нет').slice(0,4),recent=[...leads].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))).slice(0,5);return `<section class="auto-section"><div class="auto-section-head"><div><span class="auto-eyebrow">РАБОЧИЙ СТОЛ</span><h2>Сегодня у менеджера</h2></div><p>Следующие действия, расчёты, депозиты и логистика.</p></div><div class="auto-kpis auto-kpis-admin">${kpi('Активные лиды',d.activeLeads,`${d.newLeads} новых`)}${kpi('Просрочено / сегодня',due.length,'следующие действия',due.length?'alert':'')}${kpi('Расчёты открыты',d.openQuotes)}${kpi('Риски в логистике',risky.length,'требуют внимания',risky.length?'alert':'')}</div><div class="auto-panel-grid admin"><article class="auto-panel"><h3>Ближайшие действия</h3><div class="auto-stack">${due.map(l=>`<button class="auto-task" data-lead="${l.id}"><span class="auto-priority ${l.priority==='Высокий'?'high':''}">${esc(l.priority)}</span><div><b>${esc(l.name)} · ${esc(l.model)}</b><small>${esc(l.status)} · до ${dateRu(l.nextAction)}</small></div><strong>Открыть</strong></button>`).join('')||'<div class="auto-empty compact">Просроченных задач нет.</div>'}</div></article><article class="auto-panel"><h3>Риски поставок</h3><div class="auto-stack">${risky.map(o=>`<button class="auto-task" data-order="${o.id}"><span class="auto-priority high">!</span><div><b>${esc(o.model)}</b><small>${esc(orderRisk(o))} · ${esc(o.stage)}</small></div><strong>${esc(o.id)}</strong></button>`).join('')||'<div class="auto-empty compact">Рисков нет.</div>'}</div></article></div><article class="auto-panel"><div class="auto-panel-title"><h3>Последние обращения</h3><button class="auto-btn primary small" data-manager-new>+ Новый лид</button></div>${leadTable(recent)}</article></section>`}
function managerLeads(){const rows=filterLeads(leads,{query:state.leadQuery,status:state.leadStatus,source:state.leadSource,manager:state.leadManager});return `<section class="auto-section"><div class="auto-section-head"><div><span class="auto-eyebrow">CRM</span><h2>Лиды и клиенты</h2></div><button class="auto-btn primary" data-manager-new>+ Добавить лид</button></div><div class="auto-admin-filters"><input id="leadSearch" placeholder="Клиент, модель, контакт…" value="${esc(state.leadQuery)}"><select id="leadStatusFilter"><option value="all">Все статусы</option>${LEAD_STATUSES.map(x=>`<option ${state.leadStatus===x?'selected':''}>${x}</option>`).join('')}</select><select id="leadSourceFilter"><option value="all">Все источники</option>${SOURCE_OPTIONS.map(x=>`<option ${state.leadSource===x?'selected':''}>${x}</option>`).join('')}</select><select id="leadManagerFilter"><option value="all">Все менеджеры</option>${MANAGERS.map(x=>`<option ${state.leadManager===x?'selected':''}>${x}</option>`).join('')}</select></div><article class="auto-panel">${rows.length?leadTable(rows):'<div class="auto-empty">Ничего не найдено.</div>'}</article></section>`}
function quoteBreakdown(q){return `<div class="auto-quote-grid">${[['lot','Лот'],['auction','Аукцион'],['inland','Доставка США'],['ocean','Море'],['customs','Таможня'],['repair','Ремонт'],['service','Услуга']].map(([k,l])=>`<span><b>${l}</b>${money(q[k])}</span>`).join('')}</div>`}
function managerQuotes(){return `<section class="auto-section"><div class="auto-section-head"><div><span class="auto-eyebrow">РАСЧЁТЫ</span><h2>Калькуляции клиентам</h2></div><button class="auto-btn primary" data-new-quote>+ Новый расчёт</button></div><div class="auto-quote-list">${[...quotes].sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).map(q=>{const lead=leads.find(x=>x.id===q.leadId);let action='';if(q.status==='Черновик')action='<button class="auto-btn primary" data-quote-action="Отправлен" data-id="'+q.id+'">Отправить</button>';if(q.status==='Отправлен')action='<button class="auto-btn primary" data-quote-action="На согласовании" data-id="'+q.id+'">На согласовании</button>';if(q.status==='На согласовании')action='<button class="auto-btn primary" data-quote-action="Согласован" data-id="'+q.id+'">Согласовать</button>';if(['Согласован','Отказ'].includes(q.status))action='<button class="auto-btn ghost" data-clone-quote="'+q.id+'">Новая версия</button>';return `<article class="auto-quote-card"><div class="auto-quote-head"><div><span class="auto-status ${statusClass(q.status)}">${esc(q.status)}</span><h3>${esc(q.model)}</h3><small>${esc(lead?.name||q.leadId)} · v${q.version||1} · действует до ${dateRu(q.validUntil)}</small></div><div class="auto-price"><b>${money(q.total)}</b><span>под ключ</span></div></div>${quoteBreakdown(q)}<div class="auto-card-actions admin"><button class="auto-btn ghost" data-quote="${q.id}">${q.status==='Согласован'?'Открыть':'Редактировать'}</button>${action}</div></article>`}).join('')}</div></section>`}
function orderProgress(o){const idx=orderStageIndex(o.stage),p=Math.round(idx/(ORDER_STAGES.length-1)*100);return `<div class="auto-progress"><div><i style="width:${p}%"></i></div><span>${p}%</span></div>`}
function orderTable(rows,owner=false){return `<div class="auto-data-table orders"><div class="auto-data-head"><span>Заказ / клиент</span><span>Этап</span><span>ETA</span><span>${owner?'Маржа':'Локация'}</span><span>Риск</span><span></span></div>${rows.map(o=>`<button class="auto-data-row" data-order="${o.id}"><span><b>${esc(o.id)} · ${esc(o.model)}</b><small>${esc(o.customer)} · lot ${esc(o.lot||'—')} · VIN ${esc(o.vin||'—')}</small></span><span><b>${esc(o.stage)}</b>${orderProgress(o)}</span><span>${dateRu(o.eta)}</span><span>${owner?money(o.total-o.cost):esc(o.location||'—')}</span><span class="auto-status ${orderRisk(o)==='Нет'?'good':'warn'}">${esc(orderRisk(o))}</span><span class="auto-row-action">→</span></button>`).join('')}</div>`}
function managerShipping(){const rows=filterOrders(orders.map(o=>({...o,risk:orderRisk(o)})),{query:state.orderQuery,stage:state.orderStage,manager:state.orderManager,risk:state.orderRisk});return `<section class="auto-section"><div class="auto-section-head"><div><span class="auto-eyebrow">ЛОГИСТИКА</span><h2>Автомобили и контрольные точки</h2></div><p>Этап меняется последовательно; критичные поля проверяются.</p></div><div class="auto-admin-filters three"><input id="orderSearch" placeholder="Заказ, VIN, lot, клиент…" value="${esc(state.orderQuery)}"><select id="orderStageFilter"><option value="all">Все этапы</option>${ORDER_STAGES.map(x=>`<option ${state.orderStage===x?'selected':''}>${x}</option>`).join('')}</select><select id="orderRiskFilter"><option value="all">Все риски</option><option value="risk" ${state.orderRisk==='risk'?'selected':''}>Только с риском</option><option value="safe" ${state.orderRisk==='safe'?'selected':''}>Без риска</option></select></div><article class="auto-panel">${rows.length?orderTable(rows):'<div class="auto-empty">Заказов по фильтру нет.</div>'}</article></section>`}
function funnelBars(){const values=funnelStats(leads,orders),max=Math.max(...values.map(x=>x.value),1);return `<div class="auto-pipeline">${values.map(x=>`<div class="auto-pipe"><span>${esc(x.label)}</span><div class="auto-bar"><i style="width:${Math.round(x.value/max*100)}%"></i></div><b>${x.value}</b></div>`).join('')}</div>`}
function ownerOverview(){const d=dashboard(),f=finances(),ms=managerStats(leads,orders),ss=sourceStats(leads,orders);return `<section class="auto-section"><div class="auto-section-head"><div><span class="auto-eyebrow">ПАНЕЛЬ ДИРЕКТОРА</span><h2>Бизнес одним экраном</h2></div><p>Директор контролирует, но не меняет операционную логистику.</p></div><div class="auto-kpis auto-kpis-admin">${kpi('Оборот',money(f.turnover))}${kpi('Валовая маржа',money(f.margin),`${f.marginPct}%`)}${kpi('К получению',money(f.outstanding),'по заказам',f.outstanding?'alert':'')}${kpi('Конверсия',`${d.conversion}%`,`${d.deals} сделок`)}</div><div class="auto-panel-grid admin"><article class="auto-panel"><h3>Воронка продаж</h3>${funnelBars()}</article><article class="auto-panel"><h3>Контроль</h3><div class="auto-alert-list">${orders.filter(o=>orderRisk(o)!=='Нет').map(o=>`<button data-order="${o.id}"><b>${esc(o.id)} · ${esc(orderRisk(o))}</b><span>${esc(o.model)} · ${esc(o.stage)}</span></button>`).join('')||'<div class="auto-empty compact">Критичных отклонений нет.</div>'}</div></article></div><div class="auto-panel-grid admin"><article class="auto-panel"><h3>Команда</h3><div class="auto-data-table mini">${ms.map(m=>`<div class="auto-data-row static"><span><b>${esc(m.manager)}</b><small>${m.active} активных</small></span><span>${m.deals} сделки</span><span>${money(m.revenue)}</span><span>${money(m.margin)}</span></div>`).join('')}</div></article><article class="auto-panel"><h3>Источники</h3><div class="auto-data-table mini">${ss.map(s=>`<div class="auto-data-row static"><span><b>${esc(s.source)}</b><small>${s.leads} лидов</small></span><span>${s.deals} сделки</span><span>${s.conversion}%</span></div>`).join('')}</div></article></div></section>`}
function ownerPipeline(){const ss=sourceStats(leads,orders),ms=managerStats(leads,orders),lost=lostReasons(leads);return `<section class="auto-section"><div class="auto-section-head"><div><span class="auto-eyebrow">ПРОДАЖИ</span><h2>Воронка и качество лидов</h2></div></div><div class="auto-panel-grid admin"><article class="auto-panel"><h3>Воронка</h3>${funnelBars()}</article><article class="auto-panel"><h3>Источники</h3><div class="auto-data-table mini">${ss.map(s=>`<div class="auto-data-row static"><span><b>${esc(s.source)}</b><small>${s.leads} лидов</small></span><span>${s.deals}</span><span>${s.conversion}%</span></div>`).join('')}</div></article></div><div class="auto-panel-grid admin"><article class="auto-panel"><h3>Менеджеры</h3><div class="auto-data-table mini">${ms.map(m=>`<div class="auto-data-row static"><span><b>${esc(m.manager)}</b><small>${m.leads} лидов</small></span><span>${m.deals}</span><span>${money(m.revenue)}</span><span>${money(m.margin)}</span></div>`).join('')}</div></article><article class="auto-panel"><h3>Причины отказов</h3><div class="auto-stack">${lost.map(x=>`<div class="auto-reason"><b>${esc(x.reason)}</b><span>${x.count}</span></div>`).join('')||'<div class="auto-empty compact">Отказов нет.</div>'}</div></article></div></section>`}
function ownerFinance(){const f=finances();return `<section class="auto-section"><div class="auto-section-head"><div><span class="auto-eyebrow">ФИНАНСЫ</span><h2>Деньги по заказам</h2></div><p>Оплачено рассчитывается по журналу платежей.</p></div><div class="auto-kpis auto-kpis-admin">${kpi('Оборот',money(f.turnover))}${kpi('Себестоимость',money(f.cost))}${kpi('Маржа',money(f.margin),`${f.marginPct}%`)}${kpi('Дебиторка',money(f.outstanding),`${money(f.paid)} получено`,f.outstanding?'alert':'')}</div><article class="auto-panel"><div class="auto-data-table finance"><div class="auto-data-head"><span>Заказ</span><span>Цена</span><span>Себестоимость</span><span>Маржа</span><span>Оплачено</span><span>Остаток</span></div>${orders.map(o=>`<button class="auto-data-row" data-order="${o.id}"><span><b>${esc(o.id)}</b><small>${esc(o.model)}</small></span><span>${money(o.total)}</span><span>${money(o.cost)}</span><span class="auto-positive">${money(o.total-o.cost)}</span><span>${money(o.paid)}</span><span class="${o.total-o.paid?'auto-negative':''}">${money(Math.max(0,o.total-o.paid))}</span></button>`).join('')}</div></article></section>`}
function ownerOrders(){const rows=filterOrders(orders.map(o=>({...o,risk:orderRisk(o)})),{query:state.orderQuery,stage:state.orderStage,manager:state.orderManager,risk:state.orderRisk});return `<section class="auto-section"><div class="auto-section-head"><div><span class="auto-eyebrow">ЗАКАЗЫ</span><h2>Все сделки и автомобили</h2></div><p>Режим контроля без редактирования логистики.</p></div><div class="auto-admin-filters four"><input id="orderSearch" placeholder="Заказ, VIN, lot, клиент…" value="${esc(state.orderQuery)}"><select id="orderStageFilter"><option value="all">Все этапы</option>${ORDER_STAGES.map(x=>`<option ${state.orderStage===x?'selected':''}>${x}</option>`).join('')}</select><select id="orderManagerFilter"><option value="all">Все менеджеры</option>${MANAGERS.map(x=>`<option ${state.orderManager===x?'selected':''}>${x}</option>`).join('')}</select><select id="orderRiskFilter"><option value="all">Все риски</option><option value="risk" ${state.orderRisk==='risk'?'selected':''}>С риском</option><option value="safe" ${state.orderRisk==='safe'?'selected':''}>Без риска</option></select></div><article class="auto-panel">${orderTable(rows,true)}</article></section>`}

function modalRequest(prefill='',managerMode=false){if(managerMode)return `<div class="auto-modal-bg" data-modal-bg><div class="auto-modal"><div class="auto-modal-head"><div><span class="auto-eyebrow">НОВЫЙ ЛИД</span><h2>Добавить клиента в CRM</h2></div><button class="auto-close" data-close>×</button></div><form class="auto-form" id="requestForm"><input type="hidden" name="managerMode" value="1"><label>Имя клиента<input name="name" required></label><label>Контакт<input name="contact" required placeholder="Telegram / WhatsApp / телефон"></label><label>Интересующий автомобиль<input name="model" required value="${esc(prefill)}"></label><label>Бюджет, $<input name="budget" type="number" min="0" step="500"></label><label>Источник<select name="source">${SOURCE_OPTIONS.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Ответственный<select name="manager">${MANAGERS.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Приоритет<select name="priority"><option>Средний</option><option>Высокий</option><option>Низкий</option></select></label><label>Следующее действие<input name="nextAction" type="date" value="${today}" required></label><label class="full">Комментарий<textarea name="note"></textarea></label><div class="auto-form-actions"><button type="button" class="auto-btn ghost" data-close>Закрыть</button><button class="auto-btn primary" type="submit">Создать лид</button></div></form></div></div>`;return `<div class="auto-modal-bg" data-modal-bg><div class="auto-modal"><div class="auto-modal-head"><div><span class="auto-eyebrow">ЗАЯВКА</span><h2>Подобрать авто из США</h2><p class="auto-modal-sub">Только параметры автомобиля. CRM-поля заполняются автоматически.</p></div><button class="auto-close" data-close>×</button></div><form class="auto-form" id="requestForm"><input type="hidden" name="managerMode" value="0"><label>Имя<input name="name" required></label><label>Telegram / WhatsApp<input name="contact" required></label><label>Марка / модель<input name="model" required value="${esc(prefill)}"></label><label>Максимальный бюджет, $<input name="budget" required type="number" min="10000" step="500"></label><label>Год от<input name="yearFrom" type="number" min="2015" max="2026" value="2021"></label><label>Год до<input name="yearTo" type="number" min="2015" max="2026" value="2026"></label><label>Максимальный пробег, км<input name="mileageMax" type="number" min="0" step="5000" placeholder="60000"></label><label>Двигатель<select name="engine"><option>Не важно</option><option>Бензин</option><option>Гибрид</option><option>Electric</option></select></label><label>Привод<select name="drive"><option>Не важно</option><option>AWD</option><option>FWD</option><option>RWD</option></select></label><label>Повреждения<select name="damage"><option>Минимальные</option><option>Косметический ремонт допустим</option><option>Рассмотрю выгодный ремонт</option></select></label><label>Город получения<input name="deliveryCity" placeholder="Куда доставить автомобиль"></label><label class="full">Пожелания<textarea name="note" placeholder="Цвет, комплектация, важные опции…"></textarea></label><div class="auto-form-actions"><button type="button" class="auto-btn ghost" data-close>Закрыть</button><button class="auto-btn primary" type="submit">Отправить запрос</button></div></form></div></div>`}
function modalDetail(c){return `<div class="auto-modal-bg" data-modal-bg><div class="auto-modal"><div class="auto-modal-head"><div><span class="auto-eyebrow">${c.auction} · ${c.year}</span><h2>${esc(c.brand+' '+c.model)}</h2></div><button class="auto-close" data-close>×</button></div><div class="auto-car-media auto-detail-media"><img src="${c.image}" alt="${esc(c.model)}"></div><div class="auto-kpis auto-detail-kpis">${kpi('Ориентир',money(c.price))}${kpi('Пробег',c.mileage)}${kpi('Привод',c.drive)}${kpi('Срок',c.delivery)}</div><div class="auto-actions"><button class="auto-btn primary" data-request-car="${c.id}">Получить расчёт</button><button class="auto-btn ghost" data-close>Закрыть</button></div></div></div>`}
function leadStatusOptions(lead,quote){const ctx={hasAgreedQuote:quote?.status==='Согласован',deposit:lead.deposit};return LEAD_STATUSES.filter(s=>s===lead.status||leadTransitionAllowed(lead.status,s,ctx)).map(s=>`<option ${lead.status===s?'selected':''}>${s}</option>`).join('')}
function modalLead(lead){const relatedQuote=quotes.filter(x=>x.leadId===lead.id).sort((a,b)=>b.version-a.version)[0],relatedOrder=orders.find(x=>x.leadId===lead.id),history=notes[lead.id]||[],eligibility=canCreateOrder({quote:relatedQuote,deposit:lead.deposit}),agreed=relatedQuote?.status==='Согласован';return `<div class="auto-modal-bg" data-modal-bg><div class="auto-modal auto-modal-wide"><div class="auto-modal-head"><div><span class="auto-eyebrow">${esc(lead.id)} · ${esc(lead.source)}</span><h2>${esc(lead.name)} · ${esc(lead.model)}</h2></div><button class="auto-close" data-close>×</button></div><div class="auto-modal-grid"><form class="auto-form auto-form-single" id="leadEditForm"><input type="hidden" name="id" value="${lead.id}"><label>Статус<select name="status" id="leadStatus">${leadStatusOptions(lead,relatedQuote)}</select></label><label>Менеджер<select name="manager">${MANAGERS.map(x=>`<option ${lead.manager===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Имя клиента<input name="name" required value="${esc(lead.name)}"></label><label>Контакт<input name="contact" required value="${esc(lead.contact)}"></label><label>Автомобиль<input name="model" required value="${esc(lead.model)}"></label><label>Бюджет, $<input name="budget" type="number" min="0" step="500" value="${Number(lead.budget)||0}"></label><label>Источник<select name="source">${SOURCE_OPTIONS.map(x=>`<option ${lead.source===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Приоритет<select name="priority"><option ${lead.priority==='Высокий'?'selected':''}>Высокий</option><option ${lead.priority==='Средний'?'selected':''}>Средний</option><option ${lead.priority==='Низкий'?'selected':''}>Низкий</option></select></label><label>Следующее действие<input type="date" name="nextAction" value="${esc(lead.nextAction||today)}"></label><label>Год от / до<div class="auto-inline-fields"><input name="yearFrom" type="number" min="2015" max="2026" value="${esc(lead.yearFrom)}"><input name="yearTo" type="number" min="2015" max="2026" value="${esc(lead.yearTo)}"></div></label><label>Макс. пробег, км<input name="mileageMax" type="number" min="0" value="${esc(lead.mileageMax)}"></label><label>Двигатель<select name="engine">${['Не важно','Бензин','Гибрид','Electric'].map(x=>`<option ${lead.engine===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Привод<select name="drive">${['Не важно','AWD','FWD','RWD'].map(x=>`<option ${lead.drive===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Повреждения<select name="damage">${['Минимальные','Косметический ремонт допустим','Рассмотрю выгодный ремонт'].map(x=>`<option ${lead.damage===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Город получения<input name="deliveryCity" value="${esc(lead.deliveryCity)}"></label>${agreed&&!relatedOrder?`<label>Полученный депозит, $<input name="deposit" type="number" min="0" max="${relatedQuote.total}" step="100" value="${Number(lead.deposit)||0}"></label><label>Дата депозита<input name="depositDate" type="date" value="${esc(lead.depositDate||today)}"></label><label>Способ оплаты<select name="paymentMethod"><option value="">Выберите</option>${PAYMENT_METHODS.map(x=>`<option ${lead.paymentMethod===x?'selected':''}>${x}</option>`).join('')}</select></label>`:`<input type="hidden" name="deposit" value="${Number(lead.deposit)||0}"><input type="hidden" name="depositDate" value="${esc(lead.depositDate)}"><input type="hidden" name="paymentMethod" value="${esc(lead.paymentMethod)}">`}<label class="full">Заметка<textarea name="note">${esc(lead.note||'')}</textarea></label><label class="full ${lead.status==='Отказ'?'':'auto-conditional-hidden'}" id="lostReasonField">Причина отказа<input name="lostReason" value="${esc(lead.lostReason||'')}"></label><div class="auto-form-actions"><button class="auto-btn primary" type="submit">Сохранить карточку</button></div></form><aside class="auto-side-panel"><h3>Контроль сделки</h3><div class="auto-related"><div><span>Расчёт</span><b>${relatedQuote?`${relatedQuote.id} · v${relatedQuote.version} · ${relatedQuote.status}`:'не создан'}</b></div><div><span>Депозит</span><b>${lead.deposit?money(lead.deposit):'не получен'}</b></div><div><span>Заказ</span><b>${relatedOrder?`${relatedOrder.id} · ${relatedOrder.stage}`:'не создан'}</b></div></div><div class="auto-side-actions"><button class="auto-btn ghost" data-create-quote="${lead.id}">${relatedQuote?'Открыть расчёт':'Создать расчёт'}</button>${relatedOrder?`<button class="auto-btn primary" data-order="${relatedOrder.id}">Открыть заказ</button>`:`<button class="auto-btn primary" data-convert-order="${lead.id}" ${eligibility.ok?'':'disabled'}>Создать заказ</button><small class="auto-rule-hint ${eligibility.ok?'good':''}">${eligibility.ok?'Расчёт согласован и депозит зафиксирован.':esc(eligibility.reason)}</small>`}</div><h3>История</h3><div class="auto-history">${history.length?history.slice().reverse().map(x=>`<div><b>${dateTimeRu(x.at)}</b><span>${esc(x.text)}</span></div>`).join(''):'<span class="auto-muted">Изменений пока нет.</span>'}</div></aside></div></div></div>`}
function quoteAllowedStatuses(q){if(!q)return['Черновик','Отправлен'];const map={'Черновик':['Черновик','Отправлен'],'Отправлен':['Отправлен','На согласовании','Отказ'],'На согласовании':['На согласовании','Согласован','Отказ']};return map[q.status]||[q.status]}
function modalQuote(q,lead){const base=q||{id:'',leadId:lead?.id||'',model:lead?.model||'',lot:0,auction:0,inland:0,ocean:0,customs:0,repair:0,service:1500,status:'Черновик',version:1,validUntil:addDays(today,7)};if(q&&['Согласован','Отказ'].includes(q.status))return `<div class="auto-modal-bg" data-modal-bg><div class="auto-modal auto-modal-wide"><div class="auto-modal-head"><div><span class="auto-eyebrow">${esc(q.id)} · v${q.version}</span><h2>${esc(q.model)}</h2><p class="auto-modal-sub">Зафиксированная версия · ${esc(q.status)}</p></div><button class="auto-close" data-close>×</button></div>${quoteBreakdown(q)}<div class="auto-quote-total"><span>Итого под ключ</span><b>${money(q.total)}</b><small>Действует до ${dateRu(q.validUntil)}</small></div><div class="auto-actions"><button class="auto-btn primary" data-clone-quote="${q.id}">Создать новую версию</button><button class="auto-btn ghost" data-close>Закрыть</button></div></div></div>`;return `<div class="auto-modal-bg" data-modal-bg><div class="auto-modal auto-modal-wide"><div class="auto-modal-head"><div><span class="auto-eyebrow">${base.id||'НОВЫЙ РАСЧЁТ'} · v${base.version}</span><h2>${esc(base.model||'Расчёт под ключ')}</h2></div><button class="auto-close" data-close>×</button></div><form class="auto-form" id="quoteForm"><input type="hidden" name="id" value="${esc(base.id)}"><input type="hidden" name="version" value="${base.version}"><label>Лид<select name="leadId" required>${leads.filter(x=>x.status!=='Отказ').map(x=>`<option value="${x.id}" ${base.leadId===x.id?'selected':''}>${x.id} · ${esc(x.name)} · ${esc(x.model)}</option>`).join('')}</select></label><label>Автомобиль<input name="model" required value="${esc(base.model)}"></label>${[['lot','Цена лота'],['auction','Сбор аукциона'],['inland','Доставка по США'],['ocean','Морская доставка'],['customs','Таможня / оформление'],['repair','Ремонт / подготовка'],['service','Услуга компании']].map(([k,l])=>`<label>${l}, $<input name="${k}" type="number" min="0" step="50" value="${Number(base[k])||0}"></label>`).join('')}<label>Действует до<input name="validUntil" type="date" value="${esc(base.validUntil||addDays(today,7))}"></label><label>Статус<select name="status">${quoteAllowedStatuses(q).map(x=>`<option ${base.status===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="auto-quote-total full"><span>Итого под ключ</span><b id="quoteTotal">${money(calculateQuote(base))}</b><small>себестоимость без услуги: ${money(quoteCost(base))}</small></div><div class="auto-form-actions"><button type="button" class="auto-btn ghost" data-close>Отмена</button><button type="submit" class="auto-btn primary">Сохранить расчёт</button></div></form></div></div>`}
function paymentsList(order){return `<div class="auto-payment-list">${order.payments.length?order.payments.slice().reverse().map(p=>`<div><span><b>${esc(p.id)}</b>${dateRu(p.date)} · ${esc(p.method)}</span><strong>${money(p.amount)}</strong>${p.note?`<small>${esc(p.note)}</small>`:''}</div>`).join(''):'<span class="auto-muted">Платежей нет.</span>'}</div>`}
function modalOrder(order){const lead=leads.find(x=>x.id===order.leadId),risk=order.riskType||'Нет';if(state.role==='owner')return `<div class="auto-modal-bg" data-modal-bg><div class="auto-modal auto-modal-wide"><div class="auto-modal-head"><div><span class="auto-eyebrow">${esc(order.id)} · КОНТРОЛЬ</span><h2>${esc(order.model)}</h2><p class="auto-modal-sub">${esc(order.customer)} · ${esc(order.manager)}</p></div><button class="auto-close" data-close>×</button></div>${timeline(order.stage)}<div class="auto-order-meta"><span><b>LOT / VIN</b>${esc(order.lot||'—')} · ${esc(order.vin||'—')}</span><span><b>Локация / ETA</b>${esc(order.location||'—')} · ${dateRu(order.eta)}</span><span><b>Риск</b>${esc(orderRisk(order))}</span><span><b>Оплачено</b>${money(order.paid)} из ${money(order.total)}</span></div><h3>История платежей</h3>${paymentsList(order)}<div class="auto-actions"><button class="auto-btn ghost" data-close>Закрыть</button></div></div></div>`;const next=nextOrderStage(order.stage),allowed=[order.stage,...(next!==order.stage?[next]:[])];return `<div class="auto-modal-bg" data-modal-bg><div class="auto-modal auto-modal-wide"><div class="auto-modal-head"><div><span class="auto-eyebrow">${esc(order.id)} · LOT ${esc(order.lot||'—')}</span><h2>${esc(order.model)}</h2><p class="auto-modal-sub">${esc(order.customer)} · ${esc(order.manager)} · VIN ${esc(order.vin||'—')}</p></div><button class="auto-close" data-close>×</button></div>${timeline(order.stage)}<div class="auto-modal-grid"><form class="auto-form auto-form-single" id="orderForm"><input type="hidden" name="id" value="${order.id}"><label>Этап<select name="stage">${allowed.map(x=>`<option ${order.stage===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Менеджер<select name="manager">${MANAGERS.map(x=>`<option ${order.manager===x?'selected':''}>${x}</option>`).join('')}</select></label><label>LOT<input name="lot" value="${esc(order.lot||'')}"></label><label>VIN<input name="vin" value="${esc(order.vin||'')}"></label><label>ETA<input type="date" name="eta" value="${esc(order.eta||'')}"></label><label>Текущая локация<input name="location" value="${esc(order.location||'')}"></label><label>Риск<select name="riskType" id="riskType">${RISK_TYPES.map(x=>`<option ${risk===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="${risk==='Нет'?'auto-conditional-hidden':''}" id="riskNoteField">Описание риска<input name="riskNote" value="${esc(order.riskNote||'')}"></label><div class="auto-form-divider full">Новый платёж</div><label>Сумма, $<input name="paymentAmount" type="number" min="0" max="${Math.max(0,order.total-order.paid)}" step="100" value="0"></label><label>Дата<input name="paymentDate" type="date" value="${today}"></label><label>Способ<select name="paymentMethod">${PAYMENT_METHODS.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Комментарий<input name="paymentNote" placeholder="Депозит, доплата…"></label><div class="auto-form-actions"><button class="auto-btn primary" type="submit">Сохранить заказ</button></div></form><aside class="auto-side-panel"><h3>Финансы заказа</h3><div class="auto-related"><div><span>Цена клиенту</span><b>${money(order.total)}</b></div><div><span>Себестоимость</span><b>${money(order.cost)}</b></div><div><span>Оплачено</span><b>${money(order.paid)}</b></div><div><span>Остаток</span><b class="${order.total-order.paid?'auto-negative':''}">${money(Math.max(0,order.total-order.paid))}</b></div></div><h3>Платежи</h3>${paymentsList(order)}<div class="auto-side-actions">${next!==order.stage?`<button class="auto-btn ghost" data-order-next="${order.id}">Проверить и перейти: ${esc(next)}</button>`:''}${lead?`<button class="auto-btn ghost" data-lead="${lead.id}">Карточка клиента</button>`:''}</div></aside></div></div></div>`}
function modal(){const m=state.modal;if(!m)return'';if(m.type==='request')return modalRequest(m.prefill||'',!!m.managerMode);if(m.type==='detail')return modalDetail(cars.find(x=>x.id===m.id));if(m.type==='lead')return modalLead(leads.find(x=>x.id===m.id));if(m.type==='quote'){const q=quotes.find(x=>x.id===m.id),lead=leads.find(x=>x.id===(q?.leadId||m.leadId));return modalQuote(q,lead)}if(m.type==='order')return modalOrder(orders.find(x=>x.id===m.id));return''}
function page(){if(state.role==='client')return state.route==='catalog'?catalog():state.route==='orders'?clientOrders():state.route==='about'?about():home();if(state.role==='manager')return state.route==='leads'?managerLeads():state.route==='quotes'?managerQuotes():state.route==='shipping'?managerShipping():managerWork();return state.route==='pipeline'?ownerPipeline():state.route==='finance'?ownerFinance():state.route==='ordersAdmin'?ownerOrders():ownerOverview()}
function render(){root.innerHTML=shell(page())}
function focusAfterRender(id){render();queueMicrotask(()=>{const el=document.getElementById(id);if(el){el.focus();if('selectionStart'in el){const n=el.value.length;el.setSelectionRange(n,n)}}})}

function quoteAction(id,status){const q=quotes.find(x=>x.id===id);if(!q)return;const allowed=quoteAllowedStatuses(q);if(!allowed.includes(status))return;const errors=validateQuote({...q,status});if(errors.length){state.modal={type:'quote',id:q.id};render();queueMicrotask(()=>showErrors(root.querySelector('#quoteForm'),errors));return}q.status=status;q.updatedAt=new Date().toISOString();if(status==='Отправлен'&&!q.sentAt)q.sentAt=q.updatedAt;if(status==='Согласован')q.agreedAt=q.updatedAt;const lead=leads.find(x=>x.id===q.leadId);if(lead&&status!=='Отказ'&&!['Сделка','Отказ'].includes(lead.status))lead.status=status==='Черновик'?'Расчёт':'Ожидает клиента';notes[q.leadId]=notes[q.leadId]||[];notes[q.leadId].push({at:new Date().toISOString(),text:`Расчёт ${q.id} → ${status}.`});saveAll();render()}
function cloneQuote(id){const old=quotes.find(x=>x.id===id);if(!old)return;const q={...old,id:nextId('Q',quotes),version:(old.version||1)+1,status:'Черновик',validUntil:addDays(today,7),updatedAt:new Date().toISOString(),revisionOf:old.id};delete q.sentAt;delete q.agreedAt;quotes.push(q);saveAll();state.modal={type:'quote',id:q.id};render()}
function convertLeadToOrder(leadId){const lead=leads.find(x=>x.id===leadId);if(!lead)return;const existing=orders.find(x=>x.leadId===leadId);if(existing){state.modal={type:'order',id:existing.id};render();return}const q=quotes.filter(x=>x.leadId===leadId).sort((a,b)=>b.version-a.version)[0],eligibility=canCreateOrder({quote:q,deposit:lead.deposit});if(!eligibility.ok){state.modal={type:'lead',id:leadId};render();return}const payments=lead.deposit?[{id:'PAY-1',amount:Number(lead.deposit),date:lead.depositDate||today,method:lead.paymentMethod||'Банк',note:'Депозит до создания заказа'}]:[];const order={id:nextId('O',orders),leadId:lead.id,customer:lead.name,model:q.model,manager:lead.manager,source:lead.source,total:q.total,cost:quoteCost(q),paid:paymentsTotal(payments),payments,stage:'Выкуп',eta:'',lot:'',vin:'',location:'',riskType:'Нет',riskNote:'',risk:'Нет',updatedAt:new Date().toISOString()};orders.push(order);lead.status='Сделка';notes[lead.id]=notes[lead.id]||[];notes[lead.id].push({at:new Date().toISOString(),text:`После согласования расчёта и депозита создан заказ ${order.id}.`});saveAll();state.modal={type:'order',id:order.id};render()}

root.addEventListener('click',event=>{const t=event.target.closest('button,[data-modal-bg]');if(!t)return;if(t.dataset.modalBg!==undefined&&event.target===t){state.modal=null;render();return}if(t.dataset.close!==undefined){state.modal=null;render();return}if(t.dataset.role){state.role=t.dataset.role;sessionStorage.setItem(KEYS.role,state.role);state.route=nav[state.role][0][0];state.modal=null;render();return}if(t.dataset.go){state.route=t.dataset.go;state.modal=null;render();return}if(t.dataset.openRequest!==undefined){state.modal={type:'request',prefill:'',managerMode:false};render();return}if(t.dataset.managerNew!==undefined){state.modal={type:'request',prefill:'',managerMode:true};render();return}if(t.dataset.requestCar){const c=cars.find(x=>x.id===t.dataset.requestCar);state.modal={type:'request',prefill:c?`${c.brand} ${c.model}`:'',managerMode:false};render();return}if(t.dataset.detail){state.modal={type:'detail',id:t.dataset.detail};render();return}if(t.dataset.lead){state.modal={type:'lead',id:t.dataset.lead};render();return}if(t.dataset.quote){state.modal={type:'quote',id:t.dataset.quote};render();return}if(t.dataset.order){state.modal={type:'order',id:t.dataset.order};render();return}if(t.dataset.newQuote!==undefined){const lead=leads.find(x=>!['Отказ','Сделка'].includes(x.status));state.modal={type:'quote',leadId:lead?.id||''};render();return}if(t.dataset.createQuote){const existing=quotes.filter(x=>x.leadId===t.dataset.createQuote).sort((a,b)=>b.version-a.version)[0];state.modal={type:'quote',id:existing?.id||'',leadId:t.dataset.createQuote};render();return}if(t.dataset.convertOrder&&!t.disabled){convertLeadToOrder(t.dataset.convertOrder);return}if(t.dataset.quoteAction){quoteAction(t.dataset.id,t.dataset.quoteAction);return}if(t.dataset.cloneQuote){cloneQuote(t.dataset.cloneQuote);return}if(t.dataset.orderNext){const order=orders.find(x=>x.id===t.dataset.orderNext);if(!order)return;const form=root.querySelector('#orderForm'),next=nextOrderStage(order.stage);if(!form)return;form.elements.stage.value=next;const data=Object.fromEntries(new FormData(form).entries()),errors=validateOrderUpdate(data,order.stage,[order.stage,next]);if(errors.length){showErrors(form,errors);return}submitOrder(form);return}});
root.addEventListener('change',event=>{const t=event.target;if(t.id==='brandFilter'){state.brand=t.value;render()}if(t.id==='budgetFilter'){state.budget=t.value;render()}if(t.id==='leadStatusFilter'){state.leadStatus=t.value;render()}if(t.id==='leadSourceFilter'){state.leadSource=t.value;render()}if(t.id==='leadManagerFilter'){state.leadManager=t.value;render()}if(t.id==='orderStageFilter'){state.orderStage=t.value;render()}if(t.id==='orderManagerFilter'){state.orderManager=t.value;render()}if(t.id==='orderRiskFilter'){state.orderRisk=t.value;render()}if(t.id==='leadStatus'){const field=root.querySelector('#lostReasonField');if(field)field.classList.toggle('auto-conditional-hidden',t.value!=='Отказ')}if(t.id==='riskType'){const field=root.querySelector('#riskNoteField');if(field)field.classList.toggle('auto-conditional-hidden',t.value==='Нет')}});
root.addEventListener('input',event=>{const t=event.target;if(t.id==='autoSearch'){state.query=t.value;focusAfterRender('autoSearch')}if(t.id==='leadSearch'){state.leadQuery=t.value;focusAfterRender('leadSearch')}if(t.id==='orderSearch'){state.orderQuery=t.value;focusAfterRender('orderSearch')}if(t.closest('#quoteForm')&&['lot','auction','inland','ocean','customs','repair','service'].includes(t.name)){const data=Object.fromEntries(new FormData(t.closest('form')).entries()),el=document.getElementById('quoteTotal');if(el)el.textContent=money(calculateQuote(data))}});
root.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(form.id==='requestForm')submitRequest(form);if(form.id==='leadEditForm')submitLead(form);if(form.id==='quoteForm')submitQuote(form);if(form.id==='orderForm')submitOrder(form)});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.modal){state.modal=null;render()}});

function submitRequest(form){const data=Object.fromEntries(new FormData(form).entries()),managerMode=data.managerMode==='1',errors=managerMode?validateManagerLead(data):validateClientRequest(data);if(errors.length){showErrors(form,errors);return}const lead={id:nextId('L',leads),name:data.name.trim(),contact:data.contact.trim(),model:data.model.trim(),budget:Number(data.budget)||0,source:managerMode?data.source:'Mini App',manager:managerMode?data.manager:'Дмитрий',status:'Новый',priority:managerMode?data.priority:'Средний',createdAt:new Date().toISOString(),nextAction:managerMode?data.nextAction:today,note:data.note||'',clientCreated:!managerMode,yearFrom:managerMode?'':data.yearFrom||'',yearTo:managerMode?'':data.yearTo||'',mileageMax:managerMode?'':data.mileageMax||'',engine:managerMode?'Не важно':data.engine||'Не важно',drive:managerMode?'Не важно':data.drive||'Не важно',damage:managerMode?'Минимальные':data.damage||'Минимальные',deliveryCity:managerMode?'':data.deliveryCity||'',deposit:0,depositDate:'',paymentMethod:''};leads.push(lead);notes[lead.id]=[{at:new Date().toISOString(),text:'Лид создан.'}];saveAll();state.modal=null;state.role=managerMode?'manager':'client';state.route=managerMode?'leads':'orders';sessionStorage.setItem(KEYS.role,state.role);render()}
function submitLead(form){const data=Object.fromEntries(new FormData(form).entries()),lead=leads.find(x=>x.id===data.id);if(!lead)return;const q=quotes.filter(x=>x.leadId===lead.id).sort((a,b)=>b.version-a.version)[0],ctx={hasAgreedQuote:q?.status==='Согласован',deposit:Number(data.deposit)||0},errors=validateLeadUpdate(data,lead,ctx);if(Number(data.deposit)>0&&(!data.depositDate||!data.paymentMethod))errors.push('Для депозита укажите дату и способ оплаты.');if(Number(data.yearFrom)&&Number(data.yearTo)&&Number(data.yearFrom)>Number(data.yearTo))errors.push('Проверьте диапазон годов.');if(errors.length){showErrors(form,errors);return}Object.assign(lead,{status:data.status,manager:data.manager,name:data.name.trim(),contact:data.contact.trim(),model:data.model.trim(),budget:Number(data.budget)||0,source:data.source,priority:data.priority,nextAction:data.nextAction,yearFrom:data.yearFrom,yearTo:data.yearTo,mileageMax:data.mileageMax,engine:data.engine,drive:data.drive,damage:data.damage,deliveryCity:data.deliveryCity,deposit:Number(data.deposit)||0,depositDate:data.depositDate||'',paymentMethod:data.paymentMethod||'',note:data.note||'',lostReason:data.status==='Отказ'?data.lostReason:''});notes[lead.id]=notes[lead.id]||[];notes[lead.id].push({at:new Date().toISOString(),text:`Карточка обновлена: ${lead.status}, менеджер ${lead.manager}${lead.deposit?`, депозит ${money(lead.deposit)}`:''}.`});saveAll();state.modal={type:'lead',id:lead.id};render()}
function submitQuote(form){const data=Object.fromEntries(new FormData(form).entries()),lead=leads.find(x=>x.id===data.leadId);if(!lead)return;let q=quotes.find(x=>x.id===data.id);if(q&&!quoteAllowedStatuses(q).includes(data.status)){showErrors(form,['Недопустимый переход статуса расчёта.']);return}const errors=validateQuote(data);if(errors.length){showErrors(form,errors);return}const numbers={lot:Number(data.lot)||0,auction:Number(data.auction)||0,inland:Number(data.inland)||0,ocean:Number(data.ocean)||0,customs:Number(data.customs)||0,repair:Number(data.repair)||0,service:Number(data.service)||0};if(!q){q={id:nextId('Q',quotes),leadId:lead.id,version:Number(data.version)||1};quotes.push(q)}Object.assign(q,{leadId:lead.id,model:data.model.trim(),...numbers,total:calculateQuote(numbers),status:data.status,validUntil:data.validUntil,updatedAt:new Date().toISOString()});if(data.status==='Отправлен'&&!q.sentAt)q.sentAt=q.updatedAt;if(data.status==='Согласован')q.agreedAt=q.updatedAt;if(!['Сделка','Отказ'].includes(lead.status))lead.status=data.status==='Черновик'?'Расчёт':'Ожидает клиента';lead.model=q.model;notes[lead.id]=notes[lead.id]||[];notes[lead.id].push({at:new Date().toISOString(),text:`Расчёт ${q.id} v${q.version}: ${money(q.total)}, статус «${q.status}».`});saveAll();state.modal=null;state.role='manager';state.route='quotes';sessionStorage.setItem(KEYS.role,'manager');render()}
function submitOrder(form){const data=Object.fromEntries(new FormData(form).entries()),order=orders.find(x=>x.id===data.id);if(!order)return;const next=nextOrderStage(order.stage),allowed=[order.stage,...(next!==order.stage?[next]:[])],errors=validateOrderUpdate(data,order.stage,allowed);const amount=Number(data.paymentAmount)||0,remaining=Math.max(0,order.total-order.paid);if(amount>remaining)errors.push('Платёж больше остатка по заказу.');if(errors.length){showErrors(form,errors);return}Object.assign(order,{stage:data.stage,manager:data.manager,lot:data.lot.trim(),vin:data.vin.trim(),eta:data.eta,location:data.location.trim(),riskType:data.riskType,riskNote:data.riskType==='Нет'?'':data.riskNote.trim(),risk:data.riskType==='Нет'?'Нет':(data.riskNote.trim()||data.riskType),updatedAt:new Date().toISOString()});if(amount>0){order.payments.push({id:nextPaymentId(order.payments),amount,date:data.paymentDate,method:data.paymentMethod,note:data.paymentNote||''});order.paid=paymentsTotal(order.payments)}const lead=leads.find(x=>x.id===order.leadId);if(lead){lead.manager=order.manager;lead.status='Сделка'}saveAll();state.modal={type:'order',id:order.id};render()}
render();
